                v_system[((v_row * 5u) + v_col)] = bitcast<f32>(b_descriptors[cw_argument_index_1]);
                v_eyePosition = (v_eyePosition + (b_matrices[((v_m + (v_col * 4u)) + v_row)] * b_source[((v_i * 10u) + v_col)]));
                continuing {
